import json,subprocess,sys,time,pathlib
root=pathlib.Path(sys.argv[1]); launch=json.loads((root/'member-launch.json').read_text()); config=launch['config']; unit=config['controller_unit']
started=time.monotonic(); terminal={}
while time.monotonic()-started < 1860:
    p=subprocess.run(['systemctl','--user','show',unit,'--property=LoadState,ActiveState,SubState,Result,MainPID'],text=True,capture_output=True)
    terminal=dict(line.split('=',1) for line in p.stdout.splitlines() if '=' in line)
    if terminal.get('ActiveState') in ('inactive','failed') or terminal.get('LoadState')=='not-found': break
    time.sleep(.25)
else:
    subprocess.run(['systemctl','--user','stop',unit],check=False)
    terminal['observer_timeout']=True
group=pathlib.Path('/sys/fs/cgroup')/config['control_group'].lstrip('/')
for name in ('memory.peak','memory.stat','cpu.stat','io.stat'):
    try: terminal[name]= (group/name).read_text()
    except OSError as error: terminal[name]= {'unavailable': str(error)}
(root/'member-terminal.json').write_text(json.dumps(terminal,indent=2)+'\n')
subprocess.run(['systemctl','--user','stop',config['slice']],check=False)
print(json.dumps({'root':str(root),'terminal':terminal}))
if terminal.get('ActiveState')=='failed' or terminal.get('observer_timeout') or not (root/'member-result.rds').exists(): sys.exit(1)
